import math

def vec_mat(x, W):
    n = len(W[0])
    return [sum(x[i] * W[i][j] for i in range(len(x))) for j in range(n)]

def mat_mat(A, B):
    return [vec_mat(row, B) for row in A]

def two_layer_tanh(x, W1, W2):
    h = [math.tanh(v) for v in vec_mat(x, W1)]
    return vec_mat(h, W2)

