class Counter:
    def __init__(self, start):
        self.value = start

    def add(self, n):
        self.value += n
        return self.value

c = Counter(10)
print(c.add(3), c.add(5))

class Base:
    def __init__(self):
        self.ready = True

class Child(Base):
    def __init__(self, scale):
        super().__init__()
        self.scale = scale

    def run(self, x):
        return x * self.scale if self.ready else 0

obj = Child(4)
print(obj.run(7))
